  1	/**
  2	 * GUI HTTP Server
  3	 *
  4	 * Standalone Node.js HTTP server that routes requests to API handlers
  5	 * (gui/api.ts) and serves static files from gui/public/. This is a SEPARATE
  6	 * process from the MCP server — stdout logging is allowed and expected.
  7	 *
  8	 * CLI Arguments:
  9	 *   --port <n>           Listen port (default: 3420)
 10	 *   --ledger-dir <path>  Ledger root path (handled by resolveLedgerRoot())
 11	 */
 12	
 13	import { createServer } from 'node:http';
 14	import type { IncomingMessage, ServerResponse } from 'node:http';
 15	import { readFile } from 'node:fs/promises';
 16	import { join, extname, dirname, resolve } from 'node:path';
 17	import { fileURLToPath } from 'node:url';
 18	
 19	import { resolveLedgerRoot, resolveProjectDir, ORCHESTRATOR_LOGS_DIR, WORKSPACE_ROOT } from '../src/utils/ledger-root.js';
 20	import { SAFE_SLUG_REGEX } from '../src/utils/constants.js';
 21	import { captureWorkspaceVersions } from '../src/utils/workspace-versions.js';
 22	import type { WorkspaceVersions } from '../src/utils/workspace-versions.js';
 23	import { readConfigFromDisk, startConfigWatcher } from '../src/gui/config.js';
 24	import { startAutoArchiveTimer } from '../src/gui/auto-archive.js';
 25	import {
 26	  handleListRunLogs,
 27	  handleGetRunLog,
 28	} from '../src/gui/handlers/run-log-handlers.js';
 29	import {
 30	  handleListProjects,
 31	  handleGetProject,
 32	  handleGetPlanDocument,
 33	  handleGetSynthesisDocument,
 34	  handleListWorkPackages,
 35	  handleGetWorkPackage,
 36	  handleDeleteProject,
 37	  handleGetInsights,
 38	  handleGetConfig,
 39	  handleUpdateConfig,
 40	  handleResetProject,
 41	  handleGetProjectHealth,
 42	  handleGetWorkPackageOverview,
 43	  handleRenameProject,
 44	  handleArchiveProject,
 45	  handleUnarchiveProject,
 46	  handleMarkProjectComplete,
 47	  handleListDialogues,
 48	  handleGetDialogueFile,
 49	  handleListChunks,
 50	  handleGetChunkFile,
 51	  handleOrchestratorStart,
 52	  handleGetOrchestratorQueue,
 53	  handleOrchestratorKill,
 54	  handleOrchestratorDismiss,
 55	  handleGetRunStatus,
 56	  handleGetRunMetadata,
 57	  ApiError,
 58	} from './api.js';
 59	import {
 60	  handleListKnowledge,
 61	  handleUpdateKnowledge,
 62	  handleDeleteKnowledge,
 63	  handlePromoteKnowledge,
 64	  handleMoveKnowledge,
 65	} from './api-knowledge.js';
 66	import {
 67	  handleListRepos,
 68	  handleGetRepo,
 69	  handleCreateRepo,
 70	  handleUpdateRepo,
 71	  handleDeleteRepo,
 72	} from './api-repos.js';
 73	import { renderChunksToMarkdown } from './chunk-renderer.js';
 74	
 75	// ---------------------------------------------------------------------------
 76	// Path resolution (ESM-safe)
 77	// ---------------------------------------------------------------------------
 78	
 79	const __filename = fileURLToPath(import.meta.url);
 80	const __dirname = dirname(__filename);
 81	
 82	const PUBLIC_DIR = join(__dirname, 'public');
 83	
 84	// ---------------------------------------------------------------------------
 85	// CLI argument parsing
 86	// ---------------------------------------------------------------------------
 87	
 88	function getPort(): number {
 89	  const args = process.argv;
 90	  const idx = args.indexOf('--port');
 91	  if (idx !== -1 && idx + 1 < args.length) {
 92	    const p = parseInt(args[idx + 1]!, 10);
 93	    if (!isNaN(p) && p > 0) return p;
 94	  }
 95	  return 3420;
 96	}
 97	
 98	// ---------------------------------------------------------------------------
 99	// MIME types
100	// ---------------------------------------------------------------------------

101	
102	const MIME_TYPES: Record<string, string> = {
103	  '.html': 'text/html',
104	  '.css': 'text/css',
105	  '.js': 'application/javascript',
106	};
107	
108	// ---------------------------------------------------------------------------
109	// CORS helpers
110	// ---------------------------------------------------------------------------
111	
112	function corsHeaders(port: number): Record<string, string> {
113	  return {
114	    'Access-Control-Allow-Origin': `http://localhost:${port}`,
115	    'Access-Control-Allow-Methods': 'GET, POST, PUT, PATCH, DELETE, OPTIONS',
116	    'Access-Control-Allow-Headers': 'Content-Type',
117	  };
118	}
119	
120	// ---------------------------------------------------------------------------
121	// Security headers
122	// ---------------------------------------------------------------------------
123	
124	function securityHeaders(): Record<string, string> {
125	  return {
126	    'X-Content-Type-Options': 'nosniff',
127	    'X-Frame-Options': 'DENY',
128	    'Referrer-Policy': 'strict-origin-when-cross-origin',
129	    'Content-Security-Policy':
130	      "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'",
131	  };
132	}
133	
134	// ---------------------------------------------------------------------------
135	// Response helpers
136	// ---------------------------------------------------------------------------
137	
138	function sendJson(
139	  res: ServerResponse,
140	  status: number,
141	  data: unknown,
142	  port: number
143	): void {
144	  const body = JSON.stringify(data);
145	  res.writeHead(status, {
146	    'Content-Type': 'application/json',
147	    'Content-Length': Buffer.byteLength(body),
148	    ...corsHeaders(port),
149	    ...securityHeaders(),
150	  });
151	  res.end(body);
152	}
153	
154	function sendError(
155	  res: ServerResponse,
156	  status: number,
157	  code: string,
158	  message: string,
159	  port: number
160	): void {
161	  sendJson(res, status, { error: { code, message } }, port);
162	}
163	
164	export function apiErrorToStatus(code: string): number {
165	  switch (code) {
166	    case 'NOT_FOUND':
167	      return 404;
168	    case 'FORBIDDEN':
169	      return 403;
170	    case 'VALIDATION_ERROR':
171	      return 400;
172	    case 'CONFLICT':
173	      return 409;
174	    default:
175	      return 500;
176	  }
177	}
178	
179	// ---------------------------------------------------------------------------
180	// Body reading
181	// ---------------------------------------------------------------------------
182	
183	/** Maximum accepted request body size (1 MiB). */
184	export const MAX_BODY_BYTES = 1_048_576;
185	
186	/** Thrown by {@link readBody} when the request body exceeds {@link MAX_BODY_BYTES}. */
187	export class PayloadTooLargeError extends Error {
188	  constructor() {
189	    super('Payload Too Large');
190	    this.name = 'PayloadTooLargeError';
191	  }
192	}
193	
194	/**
195	 * Reads the full request body as a UTF-8 string, enforcing a size limit of
196	 * {@link MAX_BODY_BYTES} (1 MiB).
197	 *
198	 * @throws {PayloadTooLargeError} When the body exceeds the limit (detected
199	 *   either via Content-Length header pre-check or streaming byte count).
200	 *   **Callers must catch this error and return a 413 response.**
201	 *
202	 * @param req - The incoming HTTP request.
203	 * @returns The full body string.
204	 */
205	function readBody(req: IncomingMessage): Promise<string> {
206	  return new Promise((resolve, reject) => {
207	    // Content-Length pre-check: reject immediately if the declared size exceeds the limit.
208	    const declaredLength = req.headers['content-length'];
209	    if (declaredLength !== undefined) {
210	      const n = parseInt(declaredLength, 10);
211	      if (!isNaN(n) && n > MAX_BODY_BYTES) {
212	        req.resume();  // drain body data from socket buffer
213	        reject(new PayloadTooLargeError());
214	        return;
215	      }
216	    }
217	
218	    const chunks: Buffer[] = [];
219	    let totalBytes = 0;
220	    let rejected = false;
221	
222	    req.on('data', (chunk: Buffer) => {
223	      if (rejected) return;
224	      totalBytes += chunk.length;
225	      if (totalBytes > MAX_BODY_BYTES) {
226	        rejected = true;
227	        reject(new PayloadTooLargeError());
228	        // Drain remaining data so the 413 response can be sent cleanly.
229	        req.resume();
230	        return;
231	      }
232	      chunks.push(chunk);
233	    });
234	    req.on('end', () => {
235	      if (!rejected) resolve(Buffer.concat(chunks).toString('utf-8'));
236	    });
237	    req.on('error', (err) => {
238	      if (!rejected) reject(err);
239	    });
240	  });
241	}
242	
243	/**
244	 * Reads and parses the request body as JSON, enforcing the same size limit as
245	 * {@link readBody}. Throws {@link PayloadTooLargeError} for oversized bodies
246	 * and {@link ApiError} with code `VALIDATION_ERROR` for invalid JSON.
247	 *
248	 * @param req - The incoming HTTP request.
249	 * @returns The parsed JSON value.
250	 */
251	async function readJsonBody(req: IncomingMessage): Promise<unknown> {
252	  const raw = await readBody(req);
253	  try {
254	    return JSON.parse(raw);
255	  } catch {
256	    throw new ApiError('VALIDATION_ERROR', 'Invalid JSON body.');
257	  }
258	}
259	
260	// ---------------------------------------------------------------------------
261	// Router
262	// ---------------------------------------------------------------------------
263	
264	type RouteHandler = () => Promise<unknown>;
265	
266	// ---------------------------------------------------------------------------
267	// Meta helpers
268	// ---------------------------------------------------------------------------
269	
270	/**
271	 * Guards against path-traversal attacks on URL parameters that are used as
272	 * filesystem path segments.
273	 *
274	 * Rejects any segment that is empty or does not match {@link SAFE_SLUG_REGEX}
275	 * (`/^[a-z0-9][a-z0-9-]*$/`). Throws {@link ApiError} `NOT_FOUND` so that
276	 * callers receive the same status as a missing project — no information leak.
277	 *
278	 * @param segment - The raw URL parameter value to validate.
279	 */
280	function assertSafeSlug(segment: string): void {
281	  if (!segment || !SAFE_SLUG_REGEX.test(segment)) {
282	    throw new ApiError('NOT_FOUND', 'Invalid repo or slug parameter.');
283	  }
284	}
285	
286	/**
287	 * Reads the `.meta.json` for a namespaced project at
288	 * `{ledgerRoot}/{repoUrlParam}/{slugUrlParam}/.meta.json`.
289	 *
290	 * Returns the stored `repository_name` value, falling back to `repoUrlParam`
291	 * when the field is absent or null.
292	 *
293	 * When the meta file exists but contains malformed JSON, the function still
294	 * falls back to `repoUrlParam` — but writes a warning to `process.stderr`
295	 * (format: `[server] Warning: malformed .meta.json at {path} — falling back
296	 * to URL param '…'`) so operators can detect corrupt meta files during
297	 * troubleshooting. API callers always receive the fallback value in this case.
298	 *
299	 * Throws {@link ApiError} `NOT_FOUND` when the meta file does not exist —
300	 * indicating that the `{repo}/{slug}` combination is not a known project in

301	 * this ledger. This is the project-existence check for namespaced routes.
302	 * Using `NOT_FOUND` (rather than a 400 or `VALIDATION_ERROR`) is intentional
303	 * information-hiding: invalid-input and missing-project cases are
304	 * indistinguishable from the client side.
305	 *
306	 * Both `repoUrlParam` and `slugUrlParam` are validated via {@link assertSafeSlug}
307	 * before any filesystem access is attempted (defence-in-depth).
308	 */
309	export async function resolveRepoName(
310	  ledgerRoot: string,
311	  repoUrlParam: string,
312	  slugUrlParam: string,
313	): Promise<string> {
314	  assertSafeSlug(repoUrlParam);
315	  assertSafeSlug(slugUrlParam);
316	  const metaPath = join(ledgerRoot, repoUrlParam, slugUrlParam, '.meta.json');
317	  let raw: string;
318	  try {
319	    raw = await readFile(metaPath, 'utf-8');
320	  } catch {
321	    throw new ApiError('NOT_FOUND', `Project not found: ${slugUrlParam}`);
322	  }
323	  try {
324	    const meta = JSON.parse(raw) as { repository_name?: string | null };
325	    return meta.repository_name ?? repoUrlParam;
326	  } catch {
327	    // Malformed .meta.json — project directory exists, fall back to URL param.
328	    // Log to stderr so operators can detect corrupt meta files during troubleshooting.
329	    process.stderr.write(`[server] Warning: malformed .meta.json at ${metaPath} — falling back to URL param '${repoUrlParam}'\n`);
330	    return repoUrlParam;
331	  }
332	}
333	
334	/**
335	 * Matches a method + URL path to an API handler.
336	 * Returns a handler thunk or null if no route matches.
337	 */
338	function matchRoute(
339	  method: string,
340	  url: string,
341	  ledgerRoot: string,
342	  orchestratorLogsDir: string
343	): RouteHandler | null {
344	  const [path] = url.split('?') as [string];
345	  const segments = path.split('/').filter(Boolean);
346	
347	  // All API routes must start with 'api'
348	  if (segments[0] !== 'api') return null;
349	
350	  const rest = segments.slice(1);
351	
352	  // Route dispatch note:
353	  // Routes are matched by segment count (rest.length) first, then by segment values.
354	  // Because the dispatcher walks the if-else chain in declaration order, two routes
355	  // that share the same rest.length value are ordered by their position here — the
356	  // first matching branch wins and subsequent branches at the same length are shadowed.
357	  // When adding a new route with the same rest.length as an existing one (e.g. a future
358	  // /:slug/synthesis at length 3 alongside /:slug/plan), make sure the more-specific
359	  // pattern appears BEFORE the catch-all pattern at that length, or it will never match.
360	
361	  // GET /api/insights
362	  if (method === 'GET' && rest.length === 1 && rest[0] === 'insights') {
363	    return () => handleGetInsights(ledgerRoot);
364	  }
365	
366	  // GET /api/orchestrator/queue
367	  if (method === 'GET' && rest.length === 2 && rest[0] === 'orchestrator' && rest[1] === 'queue') {
368	    return () => handleGetOrchestratorQueue(orchestratorLogsDir, ledgerRoot);
369	  }
370	
371	  // GET /api/orchestrator/run-status/:filename
372	  if (method === 'GET' && rest.length === 3 && rest[0] === 'orchestrator' && rest[1] === 'run-status') {
373	    const filename = decodeURIComponent(rest[2]!);
374	    return () => handleGetRunStatus(orchestratorLogsDir, filename);
375	  }
376	
377	  // GET /api/projects
378	  if (method === 'GET' && rest.length === 1 && rest[0] === 'projects') {
379	    const qIdx = url.indexOf('?');
380	    const qStr = qIdx !== -1 ? url.slice(qIdx + 1) : '';
381	    const sp = new URLSearchParams(qStr);
382	    const params = {
383	      page: sp.get('page') ?? undefined,
384	      limit: sp.get('limit') ?? undefined,
385	      status: sp.get('status') ?? undefined,
386	      search: sp.get('search') ?? undefined,
387	      sort: sp.get('sort') ?? undefined,
388	      dir: sp.get('dir') ?? undefined,
389	      runner: sp.get('runner') ?? undefined,
390	    };
391	    return () => handleListProjects(ledgerRoot, params);
392	  }
