342	export async function handleDeleteRepo(
343	  ledgerRoot: string,
344	  repoId: string
345	): Promise<{ deleted: true }> {
346	  const registry = await loadRegistry(ledgerRoot);
347	  const index = registry.repositories.findIndex((e) => e.id === repoId);
348	  if (index === -1) {
349	    throw new ApiError('NOT_FOUND', `Repository not found: '${repoId}'.`);
350	  }
351	
352	  const updatedRepositories = registry.repositories.filter((e) => e.id !== repoId);
353	  await saveRegistry(ledgerRoot, { repositories: updatedRepositories });
354	  return { deleted: true };
355	}

